INSERT INTO `translations` (`language`, `key`, `value`) VALUES
  ('en', 'common.booking_panel.start_trip', 'Start the trip'),
  ('en', 'common.booking_panel.start_hint', 'When you’ve met, you both press “Start the trip”. With location on, we check you’re within 20 m of each other.'),
  ('en', 'common.booking_panel.start_opens', '“Start the trip” opens at {when}.'),
  ('en', 'common.booking_panel.start_waiting', 'You’ve confirmed the start — waiting for {name}.'),
  ('en', 'common.booking_panel.start_them', '{name} has confirmed the start — press “Start the trip” when you’re together.'),
  ('en', 'common.booking_panel.start_confirmed', 'Start confirmed. The trip begins as soon as {name} confirms too.'),
  ('en', 'common.booking_panel.trip_started', 'Your trip has started — enjoy it!'),
  ('en', 'common.booking_panel.start_locating', 'Checking where you are…'),
  ('en', 'common.booking_panel.start_failed', 'Couldn’t start the trip.'),
  ('en', 'common.booking_panel.guest_pending_note', 'You can withdraw until {name} confirms — you’d be refunded in full. If they don’t answer before the meeting time, it’s cancelled and you’re refunded the fee minus the platform fee.'),
  ('en', 'common.booking_panel.guide_pending_note', 'Accepting commits you to this date. Declining refunds the visitor in full. If you don’t answer, it’s cancelled at the meeting time.'),
  ('es', 'common.booking_panel.start_trip', 'Empezar el viaje'),
  ('es', 'common.booking_panel.start_hint', 'Cuando os encontréis, pulsad los dos «Empezar el viaje». Con la ubicación activada, comprobamos que estáis a menos de 20 m el uno del otro.'),
  ('es', 'common.booking_panel.start_opens', '«Empezar el viaje» estará disponible desde {when}.'),
  ('es', 'common.booking_panel.start_waiting', 'Has confirmado el inicio; esperando a {name}.'),
  ('es', 'common.booking_panel.start_them', '{name} ha confirmado el inicio: pulsa «Empezar el viaje» cuando estéis juntos.'),
  ('es', 'common.booking_panel.start_confirmed', 'Inicio confirmado. El viaje empieza en cuanto {name} también lo confirme.'),
  ('es', 'common.booking_panel.trip_started', '¡Vuestro viaje ha empezado! Disfrutadlo.'),
  ('es', 'common.booking_panel.start_locating', 'Comprobando dónde estás…'),
  ('es', 'common.booking_panel.start_failed', 'No se ha podido empezar el viaje.'),
  ('es', 'common.booking_panel.guest_pending_note', 'Puedes retirarlo hasta que {name} lo confirme y se te reembolsará íntegramente. Si no responde antes de la hora del encuentro, se cancela y se te reembolsa la tarifa menos la comisión de la plataforma.'),
  ('es', 'common.booking_panel.guide_pending_note', 'Aceptar te compromete con esta fecha. Rechazar reembolsa íntegramente al visitante. Si no respondes, se cancela a la hora del encuentro.'),
  ('fr', 'common.booking_panel.start_trip', 'Commencer le voyage'),
  ('fr', 'common.booking_panel.start_hint', 'Une fois réunis, appuyez tous les deux sur « Commencer le voyage ». Avec la localisation activée, nous vérifions que vous êtes à moins de 20 m l’un de l’autre.'),
  ('fr', 'common.booking_panel.start_opens', '« Commencer le voyage » sera disponible à partir de {when}.'),
  ('fr', 'common.booking_panel.start_waiting', 'Vous avez confirmé le début — en attente de {name}.'),
  ('fr', 'common.booking_panel.start_them', '{name} a confirmé le début — appuyez sur « Commencer le voyage » quand vous êtes ensemble.'),
  ('fr', 'common.booking_panel.start_confirmed', 'Début confirmé. Le voyage commence dès que {name} confirme aussi.'),
  ('fr', 'common.booking_panel.trip_started', 'Votre voyage a commencé — profitez-en !'),
  ('fr', 'common.booking_panel.start_locating', 'Vérification de votre position…'),
  ('fr', 'common.booking_panel.start_failed', 'Impossible de commencer le voyage.'),
  ('fr', 'common.booking_panel.guest_pending_note', 'Vous pouvez retirer votre paiement tant que {name} n’a pas confirmé — vous seriez remboursé intégralement. Sans réponse avant l’heure du rendez-vous, la réservation est annulée et vous êtes remboursé du montant moins les frais de la plateforme.'),
  ('fr', 'common.booking_panel.guide_pending_note', 'Accepter vous engage pour cette date. Refuser rembourse intégralement le visiteur. Sans réponse de votre part, la demande est annulée à l’heure du rendez-vous.'),
  ('de', 'common.booking_panel.start_trip', 'Reise starten'),
  ('de', 'common.booking_panel.start_hint', 'Wenn ihr euch getroffen habt, tippt ihr beide auf „Reise starten“. Ist die Ortung an, prüfen wir, ob ihr höchstens 20 m voneinander entfernt seid.'),
  ('de', 'common.booking_panel.start_opens', '„Reise starten“ ist ab {when} verfügbar.'),
  ('de', 'common.booking_panel.start_waiting', 'Du hast den Start bestätigt – wir warten auf {name}.'),
  ('de', 'common.booking_panel.start_them', '{name} hat den Start bestätigt – tippe auf „Reise starten“, wenn ihr zusammen seid.'),
  ('de', 'common.booking_panel.start_confirmed', 'Start bestätigt. Sobald {name} ebenfalls bestätigt, geht’s los.'),
  ('de', 'common.booking_panel.trip_started', 'Eure Reise hat begonnen – viel Spaß!'),
  ('de', 'common.booking_panel.start_locating', 'Dein Standort wird geprüft …'),
  ('de', 'common.booking_panel.start_failed', 'Die Reise konnte nicht gestartet werden.'),
  ('de', 'common.booking_panel.guest_pending_note', 'Du kannst zurückziehen, bis {name} bestätigt – dann bekommst du alles erstattet. Kommt bis zum Treffzeitpunkt keine Antwort, wird die Buchung storniert und dir die Gebühr abzüglich der Plattformgebühr erstattet.'),
  ('de', 'common.booking_panel.guide_pending_note', 'Mit der Annahme verpflichtest du dich zu diesem Termin. Bei einer Ablehnung bekommt der Besucher alles erstattet. Ohne Antwort wird die Anfrage zum Treffzeitpunkt storniert.'),
  ('zh', 'common.booking_panel.start_trip', '开始行程'),
  ('zh', 'common.booking_panel.start_hint', '见面后，你们双方都点击“开始行程”。开启定位时，我们会确认你们彼此相距不超过 20 米。'),
  ('zh', 'common.booking_panel.start_opens', '“开始行程”将于 {when} 开放。'),
  ('zh', 'common.booking_panel.start_waiting', '你已确认开始，正在等待 {name}。'),
  ('zh', 'common.booking_panel.start_them', '{name} 已确认开始——你们在一起时请点击“开始行程”。'),
  ('zh', 'common.booking_panel.start_confirmed', '已确认开始。{name} 也确认后，行程即开始。'),
  ('zh', 'common.booking_panel.trip_started', '你们的行程已开始，玩得开心！'),
  ('zh', 'common.booking_panel.start_locating', '正在确认你的位置…'),
  ('zh', 'common.booking_panel.start_failed', '无法开始行程。'),
  ('zh', 'common.booking_panel.guest_pending_note', '在 {name} 确认之前你可以撤回，并获得全额退款。如果对方在见面时间前未回复，预订将被取消，退还费用扣除平台服务费后的金额。'),
  ('zh', 'common.booking_panel.guide_pending_note', '接受即表示你承诺这个日期。拒绝会向访客全额退款。如未回复，请求将在见面时间取消。'),
  ('it', 'common.booking_panel.start_trip', 'Inizia il viaggio'),
  ('it', 'common.booking_panel.start_hint', 'Quando vi siete incontrati, premete entrambi «Inizia il viaggio». Con la posizione attiva, verifichiamo che siate a meno di 20 m l’uno dall’altro.'),
  ('it', 'common.booking_panel.start_opens', '«Inizia il viaggio» sarà disponibile da {when}.'),
  ('it', 'common.booking_panel.start_waiting', 'Hai confermato l’inizio: in attesa di {name}.'),
  ('it', 'common.booking_panel.start_them', '{name} ha confermato l’inizio: premi «Inizia il viaggio» quando siete insieme.'),
  ('it', 'common.booking_panel.start_confirmed', 'Inizio confermato. Il viaggio parte non appena conferma anche {name}.'),
  ('it', 'common.booking_panel.trip_started', 'Il vostro viaggio è iniziato: buon divertimento!'),
  ('it', 'common.booking_panel.start_locating', 'Verifica della tua posizione…'),
  ('it', 'common.booking_panel.start_failed', 'Impossibile iniziare il viaggio.'),
  ('it', 'common.booking_panel.guest_pending_note', 'Puoi ritirare il pagamento finché {name} non conferma e avrai un rimborso completo. Se non risponde entro l’orario dell’incontro, la prenotazione viene annullata e ti rimborsiamo la tariffa meno la commissione della piattaforma.'),
  ('it', 'common.booking_panel.guide_pending_note', 'Accettando ti impegni per questa data. Rifiutando, il visitatore viene rimborsato per intero. Senza risposta, la richiesta viene annullata all’orario dell’incontro.'),
  ('ja', 'common.booking_panel.start_trip', '旅を開始'),
  ('ja', 'common.booking_panel.start_hint', '会えたら、お二人とも「旅を開始」を押してください。位置情報がオンの場合、お互いが 20 m 以内にいることを確認します。'),
  ('ja', 'common.booking_panel.start_opens', '「旅を開始」は {when} から利用できます。'),
  ('ja', 'common.booking_panel.start_waiting', '開始を確認しました。{name} さんの確認を待っています。'),
  ('ja', 'common.booking_panel.start_them', '{name} さんが開始を確認しました。一緒になったら「旅を開始」を押してください。'),
  ('ja', 'common.booking_panel.start_confirmed', '開始を確認しました。{name} さんも確認すると旅が始まります。'),
  ('ja', 'common.booking_panel.trip_started', '旅が始まりました。楽しんでください！'),
  ('ja', 'common.booking_panel.start_locating', '現在地を確認しています…'),
  ('ja', 'common.booking_panel.start_failed', '旅を開始できませんでした。'),
  ('ja', 'common.booking_panel.guest_pending_note', '{name} さんが確認するまでは取り消すことができ、全額返金されます。待ち合わせ時刻までに返答がない場合は予約がキャンセルされ、料金からプラットフォーム手数料を差し引いた額が返金されます。'),
  ('ja', 'common.booking_panel.guide_pending_note', '承諾するとこの日程を約束することになります。辞退すると訪問者に全額返金されます。返答がない場合、リクエストは待ち合わせ時刻にキャンセルされます。'),
  ('ru', 'common.booking_panel.start_trip', 'Начать поездку'),
  ('ru', 'common.booking_panel.start_hint', 'Когда встретитесь, оба нажмите «Начать поездку». Если геолокация включена, мы проверим, что вы находитесь не дальше 20 м друг от друга.'),
  ('ru', 'common.booking_panel.start_opens', 'Кнопка «Начать поездку» станет доступна с {when}.'),
  ('ru', 'common.booking_panel.start_waiting', 'Вы подтвердили начало — ждём {name}.'),
  ('ru', 'common.booking_panel.start_them', '{name} подтверждает начало — нажмите «Начать поездку», когда будете вместе.'),
  ('ru', 'common.booking_panel.start_confirmed', 'Начало подтверждено. Поездка начнётся, как только {name} тоже подтвердит.'),
  ('ru', 'common.booking_panel.trip_started', 'Ваша поездка началась — приятного путешествия!'),
  ('ru', 'common.booking_panel.start_locating', 'Определяем ваше местоположение…'),
  ('ru', 'common.booking_panel.start_failed', 'Не удалось начать поездку.'),
  ('ru', 'common.booking_panel.guest_pending_note', 'Вы можете отозвать оплату, пока {name} не подтвердит, — вернём всю сумму. Если ответа не будет до времени встречи, бронирование отменится, а вам вернут сумму за вычетом комиссии платформы.'),
  ('ru', 'common.booking_panel.guide_pending_note', 'Принимая, вы берёте на себя обязательство на эту дату. При отказе посетитель получит полный возврат. Без ответа запрос отменится во время встречи.'),
  ('ko', 'common.booking_panel.start_trip', '여행 시작'),
  ('ko', 'common.booking_panel.start_hint', '만나면 두 분 모두 “여행 시작”을 눌러 주세요. 위치 서비스가 켜져 있으면 서로 20m 이내에 있는지 확인합니다.'),
  ('ko', 'common.booking_panel.start_opens', '“여행 시작”은 {when}부터 사용할 수 있습니다.'),
  ('ko', 'common.booking_panel.start_waiting', '시작을 확인했습니다. {name}님을 기다리는 중입니다.'),
  ('ko', 'common.booking_panel.start_them', '{name}님이 시작을 확인했습니다. 함께 있을 때 “여행 시작”을 눌러 주세요.'),
  ('ko', 'common.booking_panel.start_confirmed', '시작이 확인되었습니다. {name}님도 확인하면 여행이 시작됩니다.'),
  ('ko', 'common.booking_panel.trip_started', '여행이 시작되었습니다. 즐거운 시간 보내세요!'),
  ('ko', 'common.booking_panel.start_locating', '위치를 확인하는 중…'),
  ('ko', 'common.booking_panel.start_failed', '여행을 시작하지 못했습니다.'),
  ('ko', 'common.booking_panel.guest_pending_note', '{name}님이 확인하기 전까지 철회할 수 있으며 전액 환불됩니다. 만남 시간 전까지 응답이 없으면 예약이 취소되고 요금에서 플랫폼 수수료를 뺀 금액이 환불됩니다.'),
  ('ko', 'common.booking_panel.guide_pending_note', '수락하면 이 날짜에 대한 약속이 됩니다. 거절하면 방문자에게 전액 환불됩니다. 응답하지 않으면 요청은 만남 시간에 취소됩니다.'),
  ('ar', 'common.booking_panel.start_trip', 'ابدأ الرحلة'),
  ('ar', 'common.booking_panel.start_hint', 'عندما تلتقيان، اضغطا كلاكما على «ابدأ الرحلة». إذا كانت خدمة الموقع مفعّلة، نتحقق من أنكما على بُعد 20 مترًا أو أقل من بعضكما.'),
  ('ar', 'common.booking_panel.start_opens', 'يتاح زر «ابدأ الرحلة» من {when}.'),
  ('ar', 'common.booking_panel.start_waiting', 'أكّدت بدء الرحلة — بانتظار {name}.'),
  ('ar', 'common.booking_panel.start_them', 'أكّد {name} بدء الرحلة — اضغط «ابدأ الرحلة» عندما تكونان معًا.'),
  ('ar', 'common.booking_panel.start_confirmed', 'تم تأكيد البدء. تبدأ الرحلة بمجرد أن يؤكد {name} أيضًا.'),
  ('ar', 'common.booking_panel.trip_started', 'بدأت رحلتكما — استمتعا بها!'),
  ('ar', 'common.booking_panel.start_locating', 'جارٍ التحقق من موقعك…'),
  ('ar', 'common.booking_panel.start_failed', 'تعذّر بدء الرحلة.'),
  ('ar', 'common.booking_panel.guest_pending_note', 'يمكنك سحب الدفع حتى يؤكد {name} — وستسترد المبلغ كاملًا. إذا لم يصل رد قبل موعد اللقاء، يُلغى الحجز ويُعاد إليك الرسم مخصومًا منه رسوم المنصة.'),
  ('ar', 'common.booking_panel.guide_pending_note', 'القبول يُلزمك بهذا الموعد. الرفض يعيد المبلغ كاملًا إلى الزائر. إذا لم ترد، يُلغى الطلب في موعد اللقاء.'),
  ('tr', 'common.booking_panel.start_trip', 'Geziyi başlat'),
  ('tr', 'common.booking_panel.start_hint', 'Buluştuğunuzda ikiniz de “Geziyi başlat”a dokunun. Konum açıksa, birbirinize en fazla 20 m uzaklıkta olduğunuzu kontrol ederiz.'),
  ('tr', 'common.booking_panel.start_opens', '“Geziyi başlat” {when} itibarıyla kullanılabilir.'),
  ('tr', 'common.booking_panel.start_waiting', 'Başlangıcı onayladınız — {name} bekleniyor.'),
  ('tr', 'common.booking_panel.start_them', '{name} başlangıcı onayladı — birlikte olduğunuzda “Geziyi başlat”a dokunun.'),
  ('tr', 'common.booking_panel.start_confirmed', 'Başlangıç onaylandı. {name} de onayladığında gezi başlar.'),
  ('tr', 'common.booking_panel.trip_started', 'Geziniz başladı — iyi eğlenceler!'),
  ('tr', 'common.booking_panel.start_locating', 'Konumunuz kontrol ediliyor…'),
  ('tr', 'common.booking_panel.start_failed', 'Gezi başlatılamadı.'),
  ('tr', 'common.booking_panel.guest_pending_note', '{name} onaylayana kadar geri çekebilirsiniz — tamamı iade edilir. Buluşma saatine kadar yanıt gelmezse rezervasyon iptal edilir ve ücret, platform ücreti düşülerek iade edilir.'),
  ('tr', 'common.booking_panel.guide_pending_note', 'Kabul etmek sizi bu tarihe bağlar. Reddetmek ziyaretçiye tam iade sağlar. Yanıt vermezseniz talep buluşma saatinde iptal edilir.'),
  ('pt', 'common.booking_panel.start_trip', 'Iniciar a viagem'),
  ('pt', 'common.booking_panel.start_hint', 'Quando se encontrarem, toquem os dois em «Iniciar a viagem». Com a localização ativada, verificamos se estão a no máximo 20 m um do outro.'),
  ('pt', 'common.booking_panel.start_opens', '«Iniciar a viagem» fica disponível a partir de {when}.'),
  ('pt', 'common.booking_panel.start_waiting', 'Confirmou o início — a aguardar {name}.'),
  ('pt', 'common.booking_panel.start_them', '{name} confirmou o início — toque em «Iniciar a viagem» quando estiverem juntos.'),
  ('pt', 'common.booking_panel.start_confirmed', 'Início confirmado. A viagem começa assim que {name} também confirmar.'),
  ('pt', 'common.booking_panel.trip_started', 'A vossa viagem começou — aproveitem!'),
  ('pt', 'common.booking_panel.start_locating', 'A verificar onde está…'),
  ('pt', 'common.booking_panel.start_failed', 'Não foi possível iniciar a viagem.'),
  ('pt', 'common.booking_panel.guest_pending_note', 'Pode desistir até {name} confirmar; seria reembolsado na totalidade. Se não houver resposta antes da hora do encontro, é cancelada e é reembolsado o valor menos a taxa da plataforma.'),
  ('pt', 'common.booking_panel.guide_pending_note', 'Aceitar compromete-o com esta data. Recusar reembolsa o visitante na totalidade. Sem resposta, o pedido é cancelado à hora do encontro.'),
  ('el', 'common.booking_panel.start_trip', 'Έναρξη ταξιδιού'),
  ('el', 'common.booking_panel.start_hint', 'Όταν συναντηθείτε, πατήστε και οι δύο «Έναρξη ταξιδιού». Με ενεργή την τοποθεσία, ελέγχουμε ότι απέχετε το πολύ 20 μ. ο ένας από τον άλλον.'),
  ('el', 'common.booking_panel.start_opens', 'Η «Έναρξη ταξιδιού» είναι διαθέσιμη από {when}.'),
  ('el', 'common.booking_panel.start_waiting', 'Επιβεβαιώσατε την έναρξη — αναμονή για {name}.'),
  ('el', 'common.booking_panel.start_them', '{name}: επιβεβαιώθηκε η έναρξη — πατήστε «Έναρξη ταξιδιού» όταν είστε μαζί.'),
  ('el', 'common.booking_panel.start_confirmed', 'Η έναρξη επιβεβαιώθηκε. Το ταξίδι ξεκινά μόλις επιβεβαιώσει και {name}.'),
  ('el', 'common.booking_panel.trip_started', 'Το ταξίδι σας ξεκίνησε — καλή διασκέδαση!'),
  ('el', 'common.booking_panel.start_locating', 'Έλεγχος της τοποθεσίας σας…'),
  ('el', 'common.booking_panel.start_failed', 'Δεν ήταν δυνατή η έναρξη του ταξιδιού.'),
  ('el', 'common.booking_panel.guest_pending_note', 'Μπορείτε να αποσύρετε την πληρωμή μέχρι να επιβεβαιώσει {name} — θα λάβετε πλήρη επιστροφή. Αν δεν υπάρξει απάντηση πριν από την ώρα της συνάντησης, η κράτηση ακυρώνεται και σας επιστρέφεται η χρέωση μείον την προμήθεια της πλατφόρμας.'),
  ('el', 'common.booking_panel.guide_pending_note', 'Με την αποδοχή δεσμεύεστε για αυτή την ημερομηνία. Με την απόρριψη ο επισκέπτης λαμβάνει πλήρη επιστροφή. Χωρίς απάντηση, το αίτημα ακυρώνεται την ώρα της συνάντησης.'),
  ('th', 'common.booking_panel.start_trip', 'เริ่มทริป'),
  ('th', 'common.booking_panel.start_hint', 'เมื่อพบกันแล้ว ให้ทั้งสองฝ่ายกด “เริ่มทริป” หากเปิดตำแหน่งที่ตั้งไว้ เราจะตรวจสอบว่าคุณอยู่ห่างกันไม่เกิน 20 ม.'),
  ('th', 'common.booking_panel.start_opens', 'ปุ่ม “เริ่มทริป” จะใช้ได้ตั้งแต่ {when}'),
  ('th', 'common.booking_panel.start_waiting', 'คุณยืนยันการเริ่มแล้ว — กำลังรอ {name}'),
  ('th', 'common.booking_panel.start_them', '{name} ยืนยันการเริ่มแล้ว — กด “เริ่มทริป” เมื่อคุณอยู่ด้วยกัน'),
