-- Trip reminders, the 15-minute warning before an unanswered request is
-- cancelled (now refunded minus the platform fee), and starting a trip by
-- both people confirming it when they meet (with location on, within 20 m
-- of each other). See "Guide fees & bookings" in CLAUDE.md. Not re-runnable
-- (the ALTER); the translations upsert.
SET NAMES utf8mb4;

ALTER TABLE `bookings`
  ADD COLUMN `answer_reminded_at` DATETIME NULL COMMENT 'guide reminded of an unanswered request' AFTER `finished_at`,
  ADD COLUMN `expiry_warned_at` DATETIME NULL COMMENT 'both warned 15 min before an unanswered request is cancelled' AFTER `answer_reminded_at`,
  ADD COLUMN `reminded_24h_at` DATETIME NULL AFTER `expiry_warned_at`,
  ADD COLUMN `reminded_2h_at` DATETIME NULL AFTER `reminded_24h_at`,
  ADD COLUMN `guest_started_at` DATETIME NULL COMMENT 'the guest confirmed the start' AFTER `reminded_2h_at`,
  ADD COLUMN `guest_start_lat` DECIMAL(9,6) NULL AFTER `guest_started_at`,
  ADD COLUMN `guest_start_lng` DECIMAL(9,6) NULL AFTER `guest_start_lat`,
  ADD COLUMN `guide_started_at` DATETIME NULL COMMENT 'the guide confirmed the start' AFTER `guest_start_lng`,
  ADD COLUMN `guide_start_lat` DECIMAL(9,6) NULL AFTER `guide_started_at`,
  ADD COLUMN `guide_start_lng` DECIMAL(9,6) NULL AFTER `guide_start_lat`,
  ADD COLUMN `started_at` DATETIME NULL COMMENT 'both confirmed: the trip started' AFTER `guide_start_lng`;

-- Trips the clock already started began at their meeting time.
UPDATE `bookings` SET `started_at` = `meeting_at`
 WHERE `trip_status` IN ('started', 'finished') AND `meeting_at` IS NOT NULL;

ON DUPLICATE KEY UPDATE `value` = VALUES(`value`);
